func finishResponse(session model.EventSession, player model.Player, result model.EventResult, reason string) map[string]any {
	return map[string]any{
		"settled": true, "reason": reason, "session_id": session.ID, "status": session.Status,
		"result": result, "player": playerPayload(player),
	}
}

func calculateResult(session *model.EventSession, event *content.Event, erosion int) model.EventResult {
	puzzlePercent := 0
	if session.PuzzleTotal > 0 {
		puzzlePercent = session.PuzzleScore * 50 / session.PuzzleTotal
	}
	battlePercent := 50
	if event.Battle != nil {
		battlePercent = 0
		if session.BattleWon {
			battlePercent = 50
		}
	}
	quality := puzzlePercent + battlePercent
	if session.InvalidAttempts > 0 {
		quality -= minInt(20, session.InvalidAttempts*5)
	}
	if erosion >= 70 {
		quality -= 15
	}
	quality = clamp(quality, 0, 100)
	stars := 1
	if quality >= 85 {
		stars = 3
	} else if quality >= 60 {
		stars = 2
	}
	return model.EventResult{ChapterID: session.ChapterID, EventID: session.EventID, Stars: stars, PuzzleScore: session.PuzzleScore, PuzzleTotal: session.PuzzleTotal, BattleWon: session.BattleWon, RepairPercent: quality, ErosionAtEnd: erosion, InkMarksEarned: stars}
}


func usedCapacity(player model.Player) int {
	total := 0
	for _, memory := range player.Memories {
		total += memory.Capacity
	}
	return total
}

func (s *Server) playerSkills(player model.Player) map[string]bool {
	result := make(map[string]bool)
	for _, entry := range player.MemoryLedger {
		if entry.Action == "kept" {
			skill := s.catalog.Memories[entry.MemoryID].Skill
			if skill != "" {
				result[skill] = true
			}
		}
	}
	for _, memory := range player.Memories {
		if memory.Skill != "" {
			result[memory.Skill] = true
		}
	}
	return result
}

