	defer s.mu.Unlock()
	old, ok := s.db.Sessions[id]
	if !ok {
		return model.EventSession{}, os.ErrNotExist
	}
	next := cloneSession(old)
	if err := fn(&next); err != nil {
	if event.Battle != nil && (!session.BattleChecked || !session.BattleWon) {
